import itertools, json
jobs='ABCDE'
slot={'A':[0,1,4,11,3],'B':[2,3,3,2,5],'C':[4,8,2,10,8],'D':[3,2,11,3,4],'E':[10,6,10,10,4]}
trans=dict(zip(jobs,[[0,3,3,0,5],[5,0,4,2,0],[2,2,0,2,5],[0,5,5,0,5],[1,4,3,1,0]]))
def nominal(p):
    return sum(slot[j][i] for i,j in enumerate(p))+sum(trans[a][jobs.index(b)] for a,b in zip(p,p[1:]))
def incident(p,k):
    pos={j:p.index(j)+1 for j in jobs}
    if pos['A']>pos['D']: return None
    if k=='rain':
        if pos['D']==1 or pos['A']==1:return None
        return nominal(p)+6*max(0,pos['C']-1)
    if k=='road':
        if pos['C']==4 or pos['E']==2:return None
        return nominal(p)+6*max(0,pos['D']-3)
    if pos['A']==1 or pos['B']==1:return None
    return nominal(p)+10*max(0,pos['E']-2)
records=[]
for p in itertools.permutations(jobs):
    if p.index('A')>p.index('D'):continue
    neighbors=[(p,0)]
    for i in range(5):
        for j in range(i+1,5):
            q=list(p);q[i],q[j]=q[j],q[i]
            neighbors.append((tuple(q),1))
    best={}
    for k in ('rain','road','lift'):
        choices=[(incident(q,k)+fee,''.join(q)) for q,fee in neighbors if incident(q,k) is not None]
        if not choices:break
        best[k]=min(choices)
    if len(best)==3:
        records.append((nominal(p)+max(v[0] for v in best.values()),''.join(p),best))
records.sort()
score,p,best=records[0]
answer={'roster':p,'score':score,'repairs':{k:v[1] for k,v in best.items()},'repair_costs':{k:v[0] for k,v in best.items()},'feasible_count':len(records),'next_score':min(s for s,_,_ in records if s>score)}
# Independent verification: evaluate all possible final permutations by Hamming distance,
# and calculate costs directly by one-based positions and explicit transfer lookup.
lookup={(a,b):trans[a][jobs.index(b)] for a in jobs for b in jobs}
def direct(q):
    return sum(slot[q[i-1]][i-1] for i in range(1,6))+sum(lookup[(q[i],q[i+1])] for i in range(4))
check=[]
for pub in map(''.join,itertools.permutations(jobs)):
    if pub.index('A')>=pub.index('D'):continue
    minima={}
    for final in map(''.join,itertools.permutations(jobs)):
        differences=sum(a!=b for a,b in zip(pub,final))
        if differences not in (0,2) or final.index('A')>=final.index('D'):continue
        base=direct(final)+(differences==2)
        for k in ('rain','road','lift'):
            if k=='rain':
                if final[0] in 'AD':continue
                value=base+6*final.index('C')
            elif k=='road':
                if final[3]=='C' or final[1]=='E':continue
                value=base+6*max(final.index('D')-2,0)
            else:
                if final[0] in 'AB':continue
                value=base+10*max(final.index('E')-1,0)
            minima[k]=min(minima.get(k,float('inf')),value)
    if len(minima)==3:check.append((pub,direct(pub)+max(minima.values()),minima))
assert len(check)==answer['feasible_count']
assert min(v[1] for v in check)==answer['score']
assert min(v[1] for v in check if v[1]>answer['score'])==answer['next_score']
assert next(v[2] for v in check if v[0]==p)==answer['repair_costs']
payload=json.dumps(answer)
assert json.loads(payload)==answer
print(payload)
print('Verified by independent all-final-permutations evaluation; publication nominal:',nominal(p))

